<script setup lang="ts">import {ref} from 'vue';import {useRouter,useRoute} from 'vue-router';import {db,configured,isAdmin} from '../lib/supabase';const router=useRouter(),route=useRoute();const email=ref(''),password=ref(''),busy=ref(false),error=ref('');async function login(){busy.value=true;error.value='';try{const {error:e}=await db().auth.signInWithPassword({email:email.value,password:password.value});if(e)throw e;if(!(await isAdmin())){await db().auth.signOut();throw Error('Esta conta não tem permissão para administrar o catálogo.');}await router.push(String(route.query.returnTo||'/admin/catalogo'));}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false;}}</script><template><main class="login-page"><form class="login-card" @submit.prevent="login"><div class="eyebrow">PAINEL ADMINISTRATIVO</div><h1>Bem-vindo de <em>volta.</em></h1><p>Entre com sua conta autorizada no Supabase Auth.</p><div v-if="!configured" class="notice error">Configure as variáveis VITE_SUPABASE_* antes de entrar.</div><label class="field">E-mail<input type="email" v-model="email" required autocomplete="username"/></label><label class="field">Senha<input type="password" v-model="password" required autocomplete="current-password"/></label><p v-if="error" class="notice error">{{error}}</p><button class="btn primary full" :disabled="busy||!configured">{{busy?'Entrando...':'Entrar no painel'}}</button><RouterLink class="back" to="/">← Voltar ao catálogo</RouterLink></form></main></template>